function Logo({light=false}:{light?:boolean}) { return <Link href="/" className="flex items-center gap-2" data-testid="link-logo"><span className={`grid h-9 w-9 place-items-center rounded-xl ${light?'bg-[#f6b73c] text-[#18303a]':'bg-[#ee8b18] text-[#18303a]'}`}><span className="display text-lg font-bold">R</span></span><span className={`display text-xl font-bold tracking-tight ${light?'text-[#f6f3ea]':'text-[#18303a]'}`}>Rig<span className="text-[#ee8b18]">Logix</span></span></Link>; }
