function Button({children, variant='primary', className='', ...props}:{children:ReactNode;variant?:'primary'|'secondary'|'ghost'|'danger';className?:string}&ButtonHTMLAttributes<HTMLButtonElement>) { const v={primary:'bg-[#ee8b18] text-[#18303a] hover:bg-[#f5a42e]',secondary:'bg-[#18303a] text-[#f6f3ea] hover:bg-[#264752]',ghost:'border border-[#d5d0c2] bg-[#fbf9f2] text-[#18303a] hover:border-[#ee8b18]',danger:'bg-[#f6d7d1] text-[#943e32]'}[variant]; return <button className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition-all ${v} ${className}`} {...props}>{children}</button>; }
function Stat({label,value,detail,icon:Icon,accent='orange'}:{label:string;value:string;detail:string;icon:typeof Gauge;accent?:string}) { return <div className="rounded-2xl border border-[#ded9ca] bg-[#fbf9f2] p-4"><div className="mb-5 flex items-center justify-between"><span className="text-xs font-bold uppercase tracking-[.15em] text-[#68777b]">{label}</span><span className={`grid h-8 w-8 place-items-center rounded-lg ${accent==='teal'?'bg-[#d7edeb] text-[#1a7d78]':'bg-[#f9e3ba] text-[#b9680d]'}`}><Icon size={16}/></span></div><div className="display text-2xl font-bold">{value}</div><div className="mt-1 text-xs text-[#68777b]">{detail}</div></div>; }
